#include <iostream>
#include <stdexcept>
#include <string>

class DivideByZeroException : public std::runtime_error {
public:
    DivideByZeroException()
        : std::runtime_error("attempted to divide by zero") {}
};

double quotient(int numerator, int denominator) {
    if (denominator == 0) {
        throw DivideByZeroException();
    }
    return static_cast<double>(numerator) / denominator;
}

int main() {
    int a = 100;
    int b = 0;

    try {
        std::cout << "Calculating quotient...\n";
        double result = quotient(a, b);
        std::cout << "Quotient is: " << result << "\n";
    }
    catch (const DivideByZeroException& ex) {
        std::cout << "Exception occurred: " << ex.what() << "\n";
    }

    std::cout << "Program continues normally after catch.\n";
    return 0;
}

#include <iostream>
#include <exception>

void intermediateTask() {
    try {
        std::cout << "  [intermediateTask] Throwing std::exception...\n";
        throw std::exception();
    }
    catch (const std::exception&) {
        std::cout << "  [intermediateTask] Intercepted! Performing local cleanup...\n";
        std::cout << "  [intermediateTask] Rethrowing exception upward.\n";
        throw; // rethrow current exception
    }
}

int main() {
    try {
        std::cout << "[main] Calling intermediateTask...\n";
        intermediateTask();
        std::cout << "[main] This will not execute.\n";
    }
    catch (const std::exception&) {
        std::cout << "[main] Caught rethrown exception successfully.\n";
    }

    std::cout << "[main] Flow continues smoothly.\n";
    return 0;
}
